# A process check: the decision never depends on how real the video looked.
def review(req):
    reasons = []
    if req["new_payee"] and not req["callback_done"]:
        reasons.append("new payee not verified by call-back on a known number")
    if req["amount"] >= 10000 and req["approvers"] < 2:
        reasons.append("needs two approvers above 10000")
    if req["urgent_secret"]:
        reasons.append("urgency/secrecy: extra check, not a shortcut")
    return reasons or ["OK to pay"]

requests = [
    {"name": "CEO video call", "amount": 400000, "new_payee": True,
     "callback_done": False, "approvers": 1, "urgent_secret": True},
    {"name": "Usual supplier", "amount": 2500, "new_payee": False,
     "callback_done": False, "approvers": 1, "urgent_secret": False},
]
for r in requests:
    print(r["name"], "amount", r["amount"])
    for why in review(r):
        print("   -", why)
# Cost: O(1) per request. The rules ignore how convincing the caller was.
